/**
 * Captures the projection's expectations from the TypeScript timeline before the model moves
 * to Elixir: fixed Pi events go through `Timeline.reduce`, and after each step the entries
 * that changed, as the keel contract's Entry, and `Timeline.publish`'s items, changed ids,
 * and order are written to hub/test/fixtures/projection.json. Ids, times, and content are
 * fixed by the cases themselves.
 *
 * Run from the shield directory: bun keel/runtime/capture-projection.ts
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { Timeline, type TimelineEvent } from "./timeline";

type Step =
  | { events: TimelineEvent[] }
  | { notice: { level: "info" | "warning" | "error"; text: string } }
  | { decorate: { tool: string; owner: string } }
  | { undecorate: { tool: string; owner: string } };

const ev = (event: unknown) => event as TimelineEvent;
const assistant = (content: unknown[], extra: Record<string, unknown> = {}) => ({
  role: "assistant",
  content,
  ...extra,
});
const text = (value: string) => ({ type: "text", text: value });
const thinking = (value: string, extra: Record<string, unknown> = {}) => ({
  type: "thinking",
  thinking: value,
  ...extra,
});
const toolCall = (id: string, name: string, args: unknown) => ({
  type: "toolCall",
  id,
  name,
  arguments: args,
});
const update = (message: unknown) => ev({ type: "message_update", message });
const end = (message: unknown) => ev({ type: "message_end", message });
const start = (message: unknown) => ev({ type: "message_start", message });
const user = (content: unknown) =>
  start({ role: "user", content: typeof content === "string" ? [text(content)] : content });

/** A decorator whose result depends only on its own tool, as keel's codemode decorator does. */
const decorator = (tool: { args: { available: boolean; value?: unknown }; state: string; result?: { text: string } }) => ({
  state: tool.state,
  code:
    tool.args.available && typeof (tool.args.value as { code?: unknown })?.code === "string"
      ? (tool.args.value as { code: string }).code
      : null,
  output: tool.result?.text ?? null,
});

const cases: Record<string, Step[]> = {
  "streamed response with thinking and fences": [
    { events: [user("explain"), start(assistant([]))] },
    { events: [update(assistant([thinking("Let me")]))] },
    { events: [update(assistant([thinking("Let me think."), text("Here:\n\n```ts\nconst a")]))] },
    {
      events: [
        update(assistant([thinking("Let me think."), text("Here:\n\n```ts\nconst a = 1;\n```\n\nand ~~~\nraw")])),
      ],
    },
    // An update that changes nothing publishes nothing.
    {
      events: [
        update(assistant([thinking("Let me think."), text("Here:\n\n```ts\nconst a = 1;\n```\n\nand ~~~\nraw")])),
      ],
    },
    {
      events: [
        update(
          assistant([
            thinking("Let me think."),
            text("Here:\n\n```ts\nconst a = 1;\n```\n\n\n\n````md\n```\nnested\n```\n````\nDone."),
          ]),
        ),
      ],
    },
    {
      events: [
        end(
          assistant(
            [
              thinking("Let me think."),
              text("Here:\n\n```ts\nconst a = 1;\n```\n\n\n\n````md\n```\nnested\n```\n````\nDone."),
            ],
            { stopReason: "stop" },
          ),
        ),
        ev({ type: "agent_settled" }),
      ],
    },
  ],
  "withheld thinking, user images, and stop reasons": [
    {
      events: [
        user([text("look"), { type: "image", data: "iVBORw0KGgo=", mimeType: "image/png" }]),
        start(assistant([thinking("", { thinkingSignature: "sig" }), thinking("x", { redacted: true })])),
      ],
    },
    { events: [end(assistant([thinking("", { thinkingSignature: "sig" })], { stopReason: "length" }))] },
    { events: [ev({ type: "agent_settled" }), user("again"), start(assistant([]))] },
    {
      events: [
        end(assistant([], { stopReason: "error", errorMessage: "overloaded_error: Overloaded" })),
        ev({ type: "agent_settled" }),
      ],
    },
    { events: [user("third"), start(assistant([text("partial")]))] },
    { events: [end(assistant([text("partial")], { stopReason: "aborted" })), ev({ type: "agent_settled" })] },
  ],
  "tools, results, nested calls, and a decorator": [
    { decorate: { tool: "codemode", owner: "codemode" } },
    { events: [user("run"), start(assistant([text("Running.")]))] },
    {
      events: [
        update(
          assistant([
            text("Running."),
            toolCall("c1", "bash", { command: "ls", timeout: 5 }),
            toolCall("c2", "codemode", { code: "await tools.read({})" }),
          ]),
        ),
      ],
    },
    {
      events: [
        end(
          assistant(
            [
              text("Running."),
              toolCall("c1", "bash", { command: "ls -la", timeout: 5 }),
              toolCall("c2", "codemode", { code: "await tools.read({})" }),
            ],
            { stopReason: "toolUse" },
          ),
        ),
        ev({ type: "tool_execution_start", toolCallId: "c1", toolName: "bash", args: { command: "ls -la", timeout: 5 } }),
      ],
    },
    {
      events: [
        ev({
          type: "tool_execution_update",
          toolCallId: "c1",
          partialResult: { content: [text("a\nb")], details: { exit: null } },
        }),
        ev({
          type: "tool_execution_start",
          toolCallId: "c2",
          toolName: "codemode",
          args: { code: "await tools.read({})" },
        }),
      ],
    },
    {
      events: [
        ev({
          type: "tool_execution_start",
          toolCallId: "n1",
          toolName: "read",
          args: { path: "a" },
          parentToolCallId: "c2",
        }),
        ev({
          type: "tool_execution_end",
          toolCallId: "c1",
          result: { content: [text("a\nb\nc"), { type: "image", data: "AAAA", mimeType: "image/jpeg" }], details: { exit: 0 } },
          isError: false,
        }),
      ],
    },
    {
      events: [
        ev({
          type: "tool_execution_start",
          toolCallId: "n2",
          toolName: "grep",
          args: { pattern: "x" },
          parentToolCallId: "n1",
        }),
        ev({ type: "tool_execution_update", toolCallId: "n1", partialResult: "reading", parentToolCallId: "c2" }),
      ],
    },
    {
      events: [
        ev({ type: "tool_execution_end", toolCallId: "n2", result: ["not content"], isError: true, parentToolCallId: "n1" }),
        ev({ type: "tool_execution_end", toolCallId: "n1", result: "file a", isError: false, parentToolCallId: "c2" }),
      ],
    },
    {
      events: [
        end({ role: "toolResult", toolCallId: "c2", content: [text("Script completed")], details: { calls: 2 }, isError: false }),
      ],
    },
    { notice: { level: "info", text: "after the script" } },
    {
      events: [
        ev({
          type: "tool_execution_start",
          toolCallId: "n3",
          toolName: "read",
          args: { path: "late" },
          parentToolCallId: "c2",
        }),
      ],
    },
    { undecorate: { tool: "codemode", owner: "codemode" } },
    {
      events: [
        start(assistant([toolCall("c3", "write", { content: "x", path: "b" })])),
        end(assistant([toolCall("c3", "write", { content: "x", path: "b" })], { stopReason: "toolUse" })),
        ev({ type: "agent_settled" }),
      ],
    },
  ],
  "a response whose text arrives after its tool started": [
    { events: [user("go"), ev({ type: "tool_execution_start", toolCallId: "t1", toolName: "read", args: { path: "x" } })] },
    { events: [update(assistant([text("Reading first.")]))] },
    { events: [update(assistant([text("Reading first."), toolCall("t1", "read", { path: "x" })]))] },
    { events: [ev({ type: "tool_execution_end", toolCallId: "t1", result: { content: "done" }, isError: false })] },
    { events: [end(assistant([text("Reading first."), toolCall("t1", "read", { path: "x" })], { stopReason: "toolUse" })), ev({ type: "agent_settled" })] },
  ],
  "compaction, retries, custom messages, settings, and notices": [
    { notice: { level: "warning", text: "extension x: something" } },
    { events: [ev({ type: "compaction_start", reason: "threshold" })] },
    {
      events: [
        ev({
          type: "compaction_end",
          reason: "threshold",
          result: { summary: "the history so far", tokensBefore: 1234 },
          aborted: false,
        }),
      ],
    },
    { events: [ev({ type: "compaction_end", reason: "overflow", aborted: false, errorMessage: "no model" })] },
    { events: [ev({ type: "compaction_start", reason: "manual" }), ev({ type: "compaction_end", reason: "manual", aborted: true })] },
    {
      events: [
        ev({ type: "auto_retry_start", attempt: 1, maxAttempts: 3, delayMs: 50, errorMessage: "overloaded" }),
      ],
    },
    { events: [ev({ type: "agent_start" })] },
    {
      events: [
        ev({ type: "auto_retry_start", attempt: 2, maxAttempts: 3, delayMs: 100, errorMessage: "overloaded again" }),
      ],
    },
    { events: [ev({ type: "auto_retry_end", success: false, finalError: "gave up" })] },
    {
      events: [
        ev({ type: "summarization_retry_scheduled", attempt: 1, maxAttempts: 2, delayMs: 10, errorMessage: "summary failed" }),
        ev({ type: "summarization_retry_attempt_start" }),
      ],
    },
    { events: [ev({ type: "summarization_retry_finished" })] },
    {
      events: [
        ev({ type: "auto_retry_start", attempt: 1, maxAttempts: 2, delayMs: 5, errorMessage: "blip" }),
        ev({ type: "auto_retry_end", success: true }),
      ],
    },
    {
      events: [
        end({ role: "custom", customType: "note", content: "a note", display: true, details: { n: 1 } }),
        end({ role: "custom", customType: "hidden", content: "unseen", display: false }),
        end({ role: "custom", customType: "blocks", content: [text("one"), text("two")], display: true }),
      ],
    },
    {
      events: [
        ev({ type: "thinking_level_changed", level: "high" }),
        ev({ type: "model_changed", previous: "a/one", model: "b/two" }),
        ev({ type: "model_changed", previous: undefined, model: "b/two" }),
      ],
    },
    { notice: { level: "info", text: "fine" } },
    { notice: { level: "error", text: "broken" } },
  ],
};

interface Captured {
  entries: Record<string, unknown>[];
  order?: string[];
  items: unknown[];
  changed: string[];
  reorder: boolean;
}

/** An old entry as the keel contract's Entry; its tool extras come from the projected item. */
function asEntry(entry: Record<string, unknown>, items: Map<string, { data: Record<string, unknown> }>) {
  const { scope: _, content: __, ...rest } = entry;
  const wire = JSON.parse(JSON.stringify(rest)) as Record<string, unknown>;
  if (entry.kind === "tool") {
    const extra = items.get(entry.id as string)?.data.extra;
    if (extra !== undefined) wire.extra = extra;
  }
  return wire;
}

const output: { name: string; steps: Captured[] }[] = [];
for (const [name, steps] of Object.entries(cases)) {
  const timeline = new Timeline({ model: "a/one", thinking: "medium" });
  const removers = new Map<string, () => void>();
  let previous = new Map<string, string>();
  let previousOrder: string[] = [];
  const captured: Captured[] = [];
  for (const step of steps) {
    if ("events" in step) for (const event of step.events) timeline.reduce(event);
    else if ("notice" in step) timeline.notice(step.notice.level, step.notice.text);
    else if ("decorate" in step)
      removers.set(
        `${step.decorate.tool}/${step.decorate.owner}`,
        timeline.decorate(step.decorate.tool, step.decorate.owner, decorator as never),
      );
    else removers.get(`${step.undecorate.tool}/${step.undecorate.owner}`)?.();
    const published = timeline.publish();
    const items = new Map(published.items.map((item) => [item.id, item as never]));
    const entries = timeline.entries.map((entry) => asEntry(entry as never, items));
    const ids = entries.map((entry) => entry.id as string);
    const changed = entries.filter((entry) => previous.get(entry.id as string) !== JSON.stringify(entry));
    const appended = [...previousOrder, ...ids.filter((id) => !previousOrder.includes(id))];
    const inOrder = appended.length === ids.length && appended.every((id, index) => id === ids[index]);
    captured.push({
      entries: changed,
      ...(inOrder ? {} : { order: ids }),
      items: JSON.parse(JSON.stringify(published.items)),
      changed: published.changed.map((item) => item.id),
      reorder: published.order !== undefined,
    });
    previous = new Map(entries.map((entry) => [entry.id as string, JSON.stringify(entry)]));
    previousOrder = ids;
  }
  output.push({ name, steps: captured });
}

writeFileSync(
  join(import.meta.dir, "../../hub/test/fixtures/projection.json"),
  `${JSON.stringify(
    {
      $comment:
        "Captured from keel/runtime/timeline.ts of commit 66d659e, the last TypeScript model, with one read-only getter added to Timeline (`get entries() { return this.#entries; }`), by the script in `capture`: save it as keel/runtime/capture-projection.ts in that tree and run `bun keel/runtime/capture-projection.ts` from the shield directory. Each step lists the entries that changed, in the driver's Entry form, `order` when an entry was not appended, and what Timeline.publish returned: every item, the ids of changed items, and whether the order changed. Tool extras are the decorator's results the old projection computed.",
      capture: readFileSync(import.meta.path, "utf8"),
      cases: output,
    },
    null,
    1,
  )}\n`,
);
